use vstd::prelude::*;

verus! {
    /// Extracts the main diagonal of a 3×3 character matrix
    /// and appends a newline character.
    fn solve(lines: Vec<Vec<char>>) -> (res: Vec<char>)
        requires
            // We require exactly a 3×3 matrix.
            lines.len() == 3,
            lines[0].len() == 3,
            lines[1].len() == 3,
            lines[2].len() == 3,
        ensures
            // The result is always length 4:
            //  three diagonal characters plus '\n'.
            res.len() == 4,
            // And the contents are precisely the diagonal plus newline.
            res[0] == lines[0][0],
            res[1] == lines[1][1],
            res[2] == lines[2][2],
            res[3] == '\n',
    {
        vec![
            lines[0][0],  // top-left
            lines[1][1],  // center
            lines[2][2],  // bottom-right
            '\n',         // newline as the fourth element
        ]
    }
}

